 "content": "def transform(grid):
    """Fill the center of every horizontal 0-1-0 pattern with 2."""
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c - 1] == 0 and row[c] == 1 and row[c + 1] == 0:
                out[r][c] = 2
    return out
